1	// Acceptance test for the change request:
2	//   "I want to track the projects I do for clients. Let me add a project and pick which client it
3	//    is for. Show each project with the client's name."
4	//
5	// A project belongs to a client. The projects page lists every project, and each project is shown
6	// together with the NAME of the client it is for (not an id). A new project is added by giving it a
7	// name and PICKING which client it is for; once added it joins the same single list, carrying that
8	// client's name.
9	//
10	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
11	// endpoint): `clients` honours { id, name, email } and `projects` honours { id, name, clientId }.
12	import { test, expect, type Page } from '@playwright/test';
13	import { resetAndSeed } from '../support/seed';
14	
15	const projectRows = (page: Page) => page.locator('[data-testid^="project-row-"]');
16	
17	// Locate the one project row carrying the given name, regardless of its server-assigned id.
18	const projectRowNamed = (page: Page, name: string) =>
19	  projectRows(page).filter({
20	    has: page.getByTestId('project-name').getByText(name, { exact: true }),
21	  });
22	
23	test.describe('Projects', () => {
24	  test('a link in the nav opens the projects page', async ({ page }) => {
25	    await resetAndSeed({ clients: [], projects: [] });
26	
27	    await page.goto('/');
28	    // The shell and the unchanged Home empty state are still present.
29	    await expect(page.getByTestId('app-root')).toBeVisible();
30	    await expect(page.getByTestId('app-nav')).toBeVisible();
31	    await expect(page.getByTestId('home-empty')).toBeVisible();
32	
33	    // Projects is reachable from the nav; following it lands on the projects page.
34	    const navProjects = page.getByTestId('nav-projects');
35	    await expect(navProjects).toBeVisible();
36	    await navProjects.click();
37	
38	    await expect(page).toHaveURL(/\/projects$/);
39	    await expect(page.getByTestId('projects-page')).toBeVisible();
40	  });
41	
42	  test('with no projects the list shows an empty state', async ({ page }) => {
43	    // Clients may exist (they are pickable) but there are no projects yet.
44	    await resetAndSeed({
45	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
46	      projects: [],
47	    });
48	
49	    await page.goto('/projects');
50	
51	    await expect(page.getByTestId('projects-page')).toBeVisible();
52	    await expect(page.getByTestId('projects-empty')).toBeVisible();
53	    // Nothing is listed yet.
54	    await expect(projectRows(page)).toHaveCount(0);
55	  });
56	
57	  test('every seeded project is shown with its name and the name of the client it is for', async ({
58	    page,
59	  }) => {
60	    await resetAndSeed({
61	      clients: [
62	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
63	        { id: 2, name: 'Globex', email: 'contact@globex.test' },
64	      ],
65	      projects: [
66	        { id: 1, name: 'Website Redesign', clientId: 1 },
67	        { id: 2, name: 'Mobile App', clientId: 2 },
68	        { id: 3, name: 'Billing System', clientId: 1 },
69	      ],
70	    });
71	
72	    await page.goto('/projects');
73	
74	    await expect(page.getByTestId('projects-page')).toBeVisible();
75	    await expect(page.getByTestId('projects-table')).toBeVisible();
76	    await expect(page.getByTestId('projects-empty')).toHaveCount(0);
77	
78	    // Every seeded project appears as its own row, carrying its name and its client's NAME.
79	    await expect(projectRows(page)).toHaveCount(3);
80	
81	    const website = page.getByTestId('project-row-1');
82	    await expect(website).toBeVisible();
83	    await expect(website.getByTestId('project-name')).toHaveText('Website Redesign');
84	    await expect(website.getByTestId('project-client')).toHaveText('Acme Corp');
85	
86	    const mobile = page.getByTestId('project-row-2');
87	    await expect(mobile.getByTestId('project-name')).toHaveText('Mobile App');
88	    await expect(mobile.getByTestId('project-client')).toHaveText('Globex');
89	
90	    // Two projects for the same client both show that client's name.
91	    const billing = page.getByTestId('project-row-3');
92	    await expect(billing.getByTestId('project-name')).toHaveText('Billing System');
93	    await expect(billing.getByTestId('project-client')).toHaveText('Acme Corp');
94	  });
95	
96	  test('adding a project and picking its client shows it with that client name', async ({ page }) => {
97	    await resetAndSeed({
98	      clients: [
99	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
100	        { id: 2, name: 'Globex', email: 'contact@globex.test' },
