111	    await page.getByTestId('project-form-client').selectOption({ label: 'Globex' });
112	    await page.getByTestId('project-form-submit').click();
113	
114	    // The newly added project appears, carrying its name and the picked client's name. Its id is
115	    // assigned by the server, so locate the row by its content rather than a known id.
116	    const newRow = projectRowNamed(page, 'Website Redesign');
