1	// Acceptance test for the change request:
2	//   "Give me one place that lists all my invoices from every project. Show which project each one
3	//    is for. Show what stage it is at."
4	//
5	// A NEW page (invoices-page), reachable from the nav (nav-invoices), lists EVERY invoice in the
6	// app in ONE place — invoices from every project, not scoped to a single project the way the
7	// project detail page is. Each invoice is shown with WHICH PROJECT it is for (invoice-project,
8	// carrying the project's NAME, not an id) and WHAT STAGE it is at (invoice-status, the draft →
9	// sent → paid stage). When there are no invoices at all it shows an empty state
10	// (all-invoices-empty) instead of the table (all-invoices-table).
11	//
12	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's
13	// /__test__ endpoint): `clients` honours { id, name, email }, `projects` honours
14	// { id, name, clientId } and `invoices` honours { id, amount, projectId, status }.
15	import { test, expect, type Page, type Locator } from '@playwright/test';
16	import { resetAndSeed } from '../support/seed';
17	
18	const invoiceRows = (page: Page) => page.locator('[data-testid^="invoice-row-"]');
19	
20	// Each stage's status cell is matched by the WORD that names the stage, case-insensitively, so the
21	// test binds to the MEANING and not one capitalisation ("Draft"/"DRAFT"/"draft" all count). The
22	// word boundaries keep the three stages distinct from one another.
23	const DRAFT = /\bdraft\b/i;
24	const SENT = /\bsent\b/i;
